from collections import deque

def components(grid, value):
    """The connected (4-neighbor) components of cells equal to value, as sets of (i, j)."""
    h, w = len(grid), len(grid[0])
    seen = [[False]*w for _ in range(h)]
    comps = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == value and not seen[i][j]:
                comp = {(i, j)}; q = deque([(i, j)]); seen[i][j] = True
                while q:
                    a, b = q.popleft()
                    for da, db in ((1,0),(-1,0),(0,1),(0,-1)):
                        c, d = a+da, b+db
                        if 0 <= c < h and 0 <= d < w and grid[c][d] == value and not seen[c][d]:
                            seen[c][d] = True; comp.add((c, d)); q.append((c, d))
                comps.append(comp)
    return comps

def border_reachable(grid, value):
    """The set of (i, j) cells equal to value connected to the grid border."""
    h, w = len(grid), len(grid[0])
    seen = [[False]*w for _ in range(h)]
    q = deque()
    for i in range(h):
        for j in (0, w-1):
            if grid[i][j] == value and not seen[i][j]: seen[i][j] = True; q.append((i, j))
    for j in range(w):
        for i in (0, h-1):
            if grid[i][j] == value and not seen[i][j]: seen[i][j] = True; q.append((i, j))
    while q:
        a, b = q.popleft()
        for da, db in ((1,0),(-1,0),(0,1),(0,-1)):
            c, d = a+da, b+db
            if 0 <= c < h and 0 <= d < w and grid[c][d] == value and not seen[c][d]:
                seen[c][d] = True; q.append((c, d))
    return {(i, j) for i in range(h) for j in range(w) if seen[i][j]}

def is_rectangle(cells):
    """Whether a set of (i, j) cells forms a solid axis-aligned rectangle."""
    if not cells: return False
    rs = [i for i, _ in cells]; cs = [j for _, j in cells]
    return len(cells) == (max(rs)-min(rs)+1) * (max(cs)-min(cs)+1)

def fill_enclosed_rects(grid, fill=4):
    """Every background-colored region not touching the border and shaped as a solid rectangle becomes fill."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    reach = border_reachable(grid, bg)
    out = [row[:] for row in grid]
    for comp in components(grid, bg):
        if not (comp & reach) and is_rectangle(comp):
            for i, j in comp: out[i][j] = fill
    return out
'''
